        ELSE '["cashier"]'::jsonb
      END,
      activated_at = COALESCE(activated_at, now()),
      updated_at = now()
  WHERE id = v_tenant_id;

  RETURN v_result || jsonb_build_object(
    'status', 'active',
    'business_type', NULLIF(trim(p_business_type), ''),
    'enabled_modules', p_enabled_modules
  );
END;
